#!/usr/bin/env node
/**
 * Content sync script (Phase 1 — "ci-copy" strategy).
 *
 * Copies markdown content from the two sibling source-of-truth repos into
 * this repo's `content/` directory at build time:
 *
 *   ../adg_prod                -> product one-pager bodies (content/products/)
 *   ../ai-decision-governance  -> public developer/integration docs (content/docs/)
 *
 * This repo does NOT hand-edit anything under content/ — it is entirely
 * regenerated by this script. Re-run before every `next build`
 * (wired into `npm run prebuild` and the build-and-sync.yml CI workflow).
 *
 * No JSON-schema export pipeline exists in adg_prod yet (Phase 2, future) —
 * this script reads raw markdown directly, matching where things actually
 * are today. When adg_prod grows `products.json`/`domains.json` exports,
 * this script should switch to consuming those instead of raw `.md` files.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..");
const ADG_PROD = process.env.ADG_PROD_PATH ?? join(REPO_ROOT, "..", "adg_prod");
const ADG_PLATFORM =
  process.env.ADG_PLATFORM_PATH ?? join(REPO_ROOT, "..", "ai-decision-governance");

/** slug -> source path (relative to ADG_PROD) of the customer-edition one-pager. */
const PRODUCT_SOURCES: Record<string, string> = {
  governance: "product/one-pagers/governance.customer.md",
  analytics: "product/one-pagers/analytics.customer.md",
  finops: "product/one-pagers/finops.customer.md",
  "execution-intelligence": "product/one-pagers/execution-intelligence.customer.md",
  "oversight-intelligence": "product/one-pagers/oversight-intelligence.customer.md",
  "trust-risk-threat-intelligence":
    "product/one-pagers/trust-risk-threat-intelligence.customer.md",
  "executive-intelligence": "product/one-pagers/executive-intelligence.customer.md",
};

/** doc slug -> source path (relative to ADG_PLATFORM) of public developer docs. */
const DOC_SOURCES: Record<string, string> = {
  "langchain-integration-guide": "docs/developer-guides/langchain-integration-guide.md",
  "langchain-onboarding-playbook":
    "docs/developer-guides/langchain-customer-onboarding-playbook.md",
  "openai-agents-integration-guide":
    "docs/developer-guides/openai-agents-integration-guide.md",
  "openai-agents-onboarding-playbook":
    "docs/developer-guides/openai-agents-customer-onboarding-playbook.md",
  "pydantic-ai-integration-guide": "docs/developer-guides/pydantic-ai-integration-guide.md",
  "pydantic-ai-onboarding-playbook":
    "docs/developer-guides/pydantic-ai-customer-onboarding-playbook.md",
  "strands-agents-integration-guide":
    "docs/developer-guides/strands-agents-integration-guide.md",
  "strands-agents-onboarding-playbook":
    "docs/developer-guides/strands-agents-customer-onboarding-playbook.md",
  "vercel-ai-integration-guide": "docs/developer-guides/vercel-ai-integration-guide.md",
  "vercel-ai-onboarding-playbook":
    "docs/developer-guides/vercel-ai-customer-onboarding-playbook.md",
  "ontology-mapping-decision-guide":
    "docs/developer-guides/ontology-mapping-decision-guide.md",
};

function resetDir(dir: string) {
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
}

function copyWithFrontmatter(
  srcAbsPath: string,
  destAbsPath: string,
  extraFrontmatter: Record<string, string>,
) {
  if (!existsSync(srcAbsPath)) {
    throw new Error(`sync-content: source file not found: ${srcAbsPath}`);
  }
  const body = readFileSync(srcAbsPath, "utf-8");
  const frontmatterLines = Object.entries(extraFrontmatter)
    .map(([k, v]) => `${k}: ${JSON.stringify(v)}`)
    .join("\n");
  const out = `---\n${frontmatterLines}\n---\n\n${body}`;
  writeFileSync(destAbsPath, out, "utf-8");
}

function syncProducts() {
  const destDir = join(REPO_ROOT, "content", "products");
  resetDir(destDir);
  for (const [slug, relPath] of Object.entries(PRODUCT_SOURCES)) {
    const src = join(ADG_PROD, relPath);
    const dest = join(destDir, `${slug}.md`);
    copyWithFrontmatter(src, dest, {
      slug,
      source: `adg_prod/${relPath}`,
    });
    console.log(`  product  ${slug.padEnd(32)} <- ${relPath}`);
  }
}

function syncDocs() {
  const destDir = join(REPO_ROOT, "content", "docs");
  resetDir(destDir);
  for (const [slug, relPath] of Object.entries(DOC_SOURCES)) {
    const src = join(ADG_PLATFORM, relPath);
    const dest = join(destDir, `${slug}.md`);
    copyWithFrontmatter(src, dest, {
      slug,
      source: `ai-decision-governance/${relPath}`,
    });
    console.log(`  doc      ${slug.padEnd(32)} <- ${relPath}`);
  }
}

/** Raw JSON (not markdown) — copied verbatim, no frontmatter wrapping. */
const DATA_SOURCES: Record<string, string> = {
  "decision-tree.json": "product/decision-diagram/decision-tree.json",
};

function syncData() {
  const destDir = join(REPO_ROOT, "content", "data");
  resetDir(destDir);
  for (const [filename, relPath] of Object.entries(DATA_SOURCES)) {
    const src = join(ADG_PROD, relPath);
    if (!existsSync(src)) {
      throw new Error(`sync-content: source file not found: ${src}`);
    }
    const dest = join(destDir, filename);
    writeFileSync(dest, readFileSync(src, "utf-8"), "utf-8");
    console.log(`  data     ${filename.padEnd(32)} <- ${relPath}`);
  }
}

function main() {
  console.log(`Syncing content from:`);
  console.log(`  adg_prod:               ${ADG_PROD}`);
  console.log(`  ai-decision-governance: ${ADG_PLATFORM}`);
  console.log();

  if (!existsSync(ADG_PROD)) {
    throw new Error(
      `sync-content: adg_prod not found at ${ADG_PROD}. Checkout it as a sibling directory, or set ADG_PROD_PATH.`,
    );
  }
  if (!existsSync(ADG_PLATFORM)) {
    throw new Error(
      `sync-content: ai-decision-governance not found at ${ADG_PLATFORM}. Checkout it as a sibling directory, or set ADG_PLATFORM_PATH.`,
    );
  }

  syncProducts();
  syncDocs();
  syncData();

  console.log("\nContent sync complete.");
}

main();
